from .textos_relevamiento import TEXTOS as _TEXTOS_R  # noqa: E402 - el catálogo de preguntas vive aparte por tamaño
from .textos_transformaciones import TEXTOS as _TEXTOS_X  # noqa: E402 - los textos de la bitácora viven aparte por tamaño

_T.update(_TEXTOS_X)
_T.update(_TEXTOS_R)


def t(key: str, lang: str = DEFAULT_LANG) -> str:
    entry = _T.get(key)
    if not entry:
        return key
    return entry.get(lang) or entry.get(DEFAULT_LANG) or key


def all_keys() -> list[str]:
    return sorted(_T)
